import {deflateSync} from 'node:zlib';
import {VISUAL_SKILLS,VISUAL_CHECKS,TASTE_REFERENCES} from '../../src/visual-design.js';
import {SPECIALISTS} from '../../src/specialist-routing.js';
export const planFor=(id='reading-cover',copyIds=['c1','c2','c3'])=>({version:1,skills:VISUAL_SKILLS.map(id=>({id,sources:['/workspace/skills/'+id+'/SKILL.md',...(id==='taste-skill'?TASTE_REFERENCES.map(reference=>'/workspace/skills/'+id+'/'+reference):[])]})),pages:[{id,copyIds,role:'正文解释页',firstFocus:'主要结论',readingOrder:['标题','分组正文'],layout:'分组排版',imageRole:'无图片，以文字关系组织画面',rationale:'让同类内容相邻，强调阅读顺序',sourceHandling:'保留全部原文和页面范围',alternatives:['标题与正文沿同一轴线组织','左右分区比较实际内容','以步骤顺序安排内容'],techniques:[{skillId:'victor-design',action:'建立主题对应的主次关系',cause:'让读者首先看到本页任务'},{skillId:'xhs-poster-composition',action:'将同类文字按邻近关系分组',cause:'降低长段的阅读负担'},{skillId:'xhs-design-polish',action:'按语义断行并检查实际手机图',cause:'保证中文阅读连贯'},{skillId:'taste-skill',action:'沿同一阅读轴对齐主题与分组正文，调整层级间距',cause:'本页有连续说明文字，需要明确的主次与适度留白'}]}]});
export function specialistPlanFor(id='reading-cover',copyIds=['c1','c2','c3'],{needs=['knowledge'],selected=['xhs-note-creator']}={}){const plan=planFor(id,copyIds);plan.pages[0].specialistNeeds=needs;plan.specialists=SPECIALISTS.map(spec=>({skillId:spec.id,status:selected.includes(spec.id)?'use':'skip',mode:selected.includes(spec.id)?'methods':'none',pageIds:selected.includes(spec.id)?[id]:[],reason:selected.includes(spec.id)?'采用该模块的分组与阅读组织方法，保留当前原文':'本页没有该模块的主要内容任务，采用更合适的阅读结构'}));for(const skillId of selected){const spec=SPECIALISTS.find(spec=>spec.id===skillId),prefix='/workspace/skills/'+skillId+'/';plan.skills.push({id:skillId,sources:[prefix+'SKILL.md',prefix+spec.references[0]]});plan.pages[0].techniques.push({skillId,action:'按参考中的内容分组与阅读顺序重排本页',cause:'当前内容有多个需要清楚辨认的阅读单元'});}return plan;}
export function reviewFor(ids=['reading-cover'],revise=false){return {summary:revise?'构图存在需要修正的问题':'当前画面的阅读关系清晰',pages:ids.map(pageId=>({pageId,checks:VISUAL_CHECKS.map((topic,index)=>({topic,judgment:revise&&index===0?'revise':'pass',observation:revise&&index===0?'照片压过标题和核心说明':'该项可见关系清楚，没有明显冲突',fix:revise&&index===0?'缩小配图并重新组织相邻正文':'保留当前处理'}))})),series:{judgment:ids.length===1?'advisory':'pass',observation:ids.length===1?'只有本页，不能判断其他页面的节奏':'提供的页面保持共同身份，结构按内容变化',fix:'保持本次授权范围'}};}
export const responseFor=value=>({status:'completed',output:[{type:'message',content:[{type:'output_text',text:JSON.stringify(value)}]}]});
function crc(bytes){let value=0xffffffff;for(const byte of bytes){value^=byte;for(let bit=0;bit<8;bit++)value=value&1?(value>>>1)^0xedb88320:value>>>1;}return (value^0xffffffff)>>>0;}
function chunk(type,data){const content=Buffer.concat([Buffer.from(type),data]),length=Buffer.alloc(4),checksum=Buffer.alloc(4);length.writeUInt32BE(data.length);checksum.writeUInt32BE(crc(content));return Buffer.concat([length,content,checksum]);}
export function phonePNG(tint=255){const header=Buffer.alloc(13);header.writeUInt32BE(360);header.writeUInt32BE(480,4);header[8]=8;header[9]=6;const rows=Buffer.alloc(480*(360*4+1),tint);for(let y=0;y<480;y++){rows[y*1441]=0;for(let x=0;x<360;x++)rows[y*1441+x*4+4]=255;}return Buffer.concat([Buffer.from('89504e470d0a1a0a','hex'),chunk('IHDR',header),chunk('IDAT',deflateSync(rows)),chunk('IEND',Buffer.alloc(0))]);}
